#include <iostream>  #################
#include <vector>    ### ITERATION ###
                     #################

// Please complete the function to iteratively perform binary search. 
// Parameters: arr - vector to be searched, 
//               x - integer to find
int binarySearch(const std::vector<int>& arr, int x) {
    int left = 0, right = arr.size() - 1;

    // loop header
    while (left <= right) {
        // loop body
        int mid = left + (right - left) / 2;

        if (arr[mid] == x)
            return mid;

        if (arr[mid] < x)
            left = mid + 1;
        else
            right = mid - 1;
    }

    return -1;
}

int main() {
    std::vector<int> arr = {2, 3, 4, 10, 40};
    int x = 10;
    int result = binarySearch(arr, x);
    if(result == -1)
        std::cout << "Element is not present in array" << std::endl;
    else
        std::cout << "Element is present at index " << result << std::endl;
    return 0;
}

#include <iostream>  #################
                     ### ITERATION ###
                     #################

// Please complete the function to iteratively calculate 
// the nth Fibonacci number.
// Parameters: n - index for number in fibonacci sequence
int fibonacci(int n) {
    if (n <= 1) return n;
    int first = 0, second = 1, fibonacci = 0;

    // loop header
    for (int i = 2; i <= n; i++) {
        // loop body
        fibonacci = first + second;
        first = second;
        second = fibonacci;
    }

    return fibonacci;
}

int main() {
    int number = 5;
    std::cout << "The " << number << "th Fibonacci number is: " << fibonacci(number) << std::endl;
    return 0;
}

#include <iostream>  #################
#include <string>    ### ITERATION ###
                     #################

// Please complete the function to iteratively check 
// if a given string is a palindrome.
// Parameters: str - string to be checked
bool isPalindrome(const std::string& str) {
    int start = 0;
    int end = str.length() - 1;

    // loop header
    while (start < end) {
        // loop body
        if (str[start] != str[end]) {
            return false;
        }
        start++;
        end--;
    }

    return true;
}

int main() {
    std::string str = "racecar";
    if (isPalindrome(str))
        std::cout << "\"" << str << "\" is a palindrome." << std::endl;
    else
        std::cout << "\"" << str << "\" is not a palindrome." << std::endl;
    return 0;
}

#include <iostream>  #################
#include <string>    ### ITERATION ###
                     #################

// Please complete the function to iteratively reverse 
// a given string.
// std::swap(a, b) may be useful
// Parameters: str - string to be reversed
void reverseString(std::string &str) {
    int start = 0;
    int end = str.length() - 1;

    // loop header
    while (start < end) {
        // loop body
        std::swap(str[start], str[end]);
        start++;
        end--;
    }
}

int main() {
    std::string str = "Hello World";
    reverseString(str);
    std::cout << "Reversed string: " << str << std::endl;
    return 0;
}

#include <iostream>  #################
#include <stack>     ### ITERATION ###
#include <vector>    #################

// Please complete the function to iteratively reverse a given stack.
// Parameters: st - stack to be reversed
void reverseStack(std::stack<int>& st) {
    std::vector<int> elements;

    // loop header 1
    while (!st.empty()) {
        // loop body 1
        elements.push_back(st.top());
        st.pop();
    }

    // loop header 2
    for (int i = elements.size() - 1; i >= 0; --i) {
        // loop body 2
        st.push(elements[i]);
    }

    // return statement

}

int main() {
    std::stack<int> st;
    st.push(1);
    st.push(2);
    st.push(3);
    st.push(4);

    reverseStack(st);

    while (!st.empty()) {
        std::cout << st.top() << " ";
        st.pop();
    }

    return 0;
}

#include <iostream>  #################
