// Please complete the function to iteratively calculate 
// the sum of first n natural numbers
// Parameters: n - quantity of natural numbers to consider
int sumOfNaturalNumbers(int n) {
    int sum = 0;

    // loop header
    for (int i = 1; i <= n; i++) {
        sum += i; // active flow
    }
    return sum;
}

int main() {
    int number = 10;
    std::cout << "Sum of first " << number << " natural numbers is: " << sumOfNaturalNumbers(number) << std::endl;
    return 0;
}

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def is_symmetric_iterative(root) -> bool:
    if not root:
        return True

    queue = [root, root]  # Start by comparing the root with itself

    while len(queue) > 0:
        left = queue.pop(0)
        right = queue.pop(0)

        if not left and not right:
            continue
        if not left or not right or left.val != right.val:
            return False

        # Enqueue children in the order needed to check for symmetry
        queue.append(left.left)
        queue.append(right.right)
        queue.append(left.right)
        queue.append(right.left)

    return True
